package com.pandinila.broadband_management.controller;import com.pandinila.broadband_management.entity.*;import com.pandinila.broadband_management.entity.Enums.*;import com.pandinila.broadband_management.repository.*;import com.pandinila.broadband_management.service.*;import org.springframework.web.bind.annotation.*;import java.util.*;import java.util.function.Function;import java.util.stream.Collectors;
@RestController @RequestMapping("/api/dashboard") public class DashboardController {private final CustomerService customers;private final MonitoringService monitoring;private final IncidentRepository incidents;public DashboardController(CustomerService c,MonitoringService m,IncidentRepository i){customers=c;monitoring=m;incidents=i;}private List<ComplaintPrediction> latest(){return customers.all().stream().map(monitoring::latestPrediction).flatMap(Optional::stream).toList();}@GetMapping("/summary") public Map<String,Object> summary(){List<Customer> cs=customers.all();List<ComplaintPrediction> ps=latest();double avg=cs.stream().map(monitoring::latestQuality).flatMap(Optional::stream).mapToDouble(ServiceQuality::getQualityScore).average().orElse(0);return Map.of("totalCustomers",cs.size(),"healthyCustomers",ps.stream().filter(p->p.getRiskLevel()==RiskLevel.LOW).count(),"atRiskCustomers",ps.stream().filter(p->p.getRiskLevel()!=RiskLevel.LOW).count(),"highRiskCustomers",ps.stream().filter(p->p.getRiskLevel()==RiskLevel.HIGH).count(),"predictedComplaints",ps.stream().filter(p->p.getRiskLevel()==RiskLevel.HIGH).count(),"activeIncidents",incidents.countByStatusIn(List.of(IncidentStatus.NEW,IncidentStatus.ASSIGNED,IncidentStatus.IN_PROGRESS,IncidentStatus.ON_HOLD)),"resolvedIncidents",incidents.countByStatusIn(List.of(IncidentStatus.RESOLVED,IncidentStatus.CLOSED)),"averageServiceQuality",Math.round(avg*100.0)/100.0);}@GetMapping("/risk-distribution") public Map<RiskLevel,Long> risk(){return latest().stream().collect(Collectors.groupingBy(ComplaintPrediction::getRiskLevel,Collectors.counting()));}@GetMapping("/network-quality") public Map<QualityLevel,Long> quality(){return customers.all().stream().map(monitoring::latestQuality).flatMap(Optional::stream).collect(Collectors.groupingBy(ServiceQuality::getQualityLevel,Collectors.counting()));}@GetMapping("/incident-summary") public Map<IncidentStatus,Long> incident(){return incidents.findAll().stream().collect(Collectors.groupingBy(Incident::getStatus,Collectors.counting()));}}
